CREATE TABLE "${primehrSchema}".spms_success_indicator(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,code VARCHAR(80) NOT NULL,normalized_code VARCHAR(80) NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT uk_spms_success_indicator_code UNIQUE(agency_id,normalized_code));
CREATE TABLE "${primehrSchema}".spms_success_indicator_version(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,success_indicator_id VARCHAR(36) NOT NULL,policy_version_id VARCHAR(36) NOT NULL,rating_scale_version_id VARCHAR(36) NOT NULL,definition_version INTEGER NOT NULL,supersedes_id VARCHAR(36),title VARCHAR(200) NOT NULL,description VARCHAR(2000),output_description VARCHAR(2000) NOT NULL,key_result_area VARCHAR(500) NOT NULL,performance_indicator VARCHAR(1000) NOT NULL,success_statement VARCHAR(2000) NOT NULL,measure_type VARCHAR(30) NOT NULL,unit_of_measure VARCHAR(100) NOT NULL,direction VARCHAR(30) NOT NULL,target_value NUMERIC(19,6),target_from NUMERIC(19,6),target_to NUMERIC(19,6),requires_evidence BOOLEAN NOT NULL,evidence_requirements VARCHAR(2000),status VARCHAR(20) NOT NULL,content_revision INTEGER NOT NULL DEFAULT 0,effective_from DATE,effective_to DATE,published_by VARCHAR(100),published_at TIMESTAMP WITH TIME ZONE,retired_by VARCHAR(100),retired_at TIMESTAMP WITH TIME ZONE,retirement_reason VARCHAR(1000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_spms_si_root FOREIGN KEY(success_indicator_id) REFERENCES "${primehrSchema}".spms_success_indicator(id),CONSTRAINT fk_spms_si_policy FOREIGN KEY(policy_version_id) REFERENCES "${primehrSchema}".spms_policy_version(id),CONSTRAINT fk_spms_si_scale FOREIGN KEY(rating_scale_version_id) REFERENCES "${primehrSchema}".spms_rating_scale_version(id),CONSTRAINT fk_spms_si_prior FOREIGN KEY(supersedes_id) REFERENCES "${primehrSchema}".spms_success_indicator_version(id),CONSTRAINT uk_spms_success_indicator_version UNIQUE(agency_id,success_indicator_id,definition_version),CONSTRAINT ck_spms_si_status CHECK(status IN ('DRAFT','PUBLISHED','RETIRED')),CONSTRAINT ck_spms_si_effective CHECK(effective_to IS NULL OR effective_from IS NULL OR effective_to>=effective_from));
CREATE TABLE "${primehrSchema}".spms_indicator_dimension(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,indicator_version_id VARCHAR(36) NOT NULL,dimension_type VARCHAR(30) NOT NULL,dimension_code VARCHAR(80) NOT NULL,label VARCHAR(200) NOT NULL,weight_percent NUMERIC(7,4) NOT NULL,display_order INTEGER NOT NULL,record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_spms_dimension_indicator FOREIGN KEY(indicator_version_id) REFERENCES "${primehrSchema}".spms_success_indicator_version(id),CONSTRAINT uk_spms_indicator_dimension_code UNIQUE(agency_id,indicator_version_id,dimension_code),CONSTRAINT uk_spms_indicator_dimension_order UNIQUE(agency_id,indicator_version_id,display_order),CONSTRAINT ck_spms_dimension_type CHECK(dimension_type IN ('QUALITY','EFFICIENCY','TIMELINESS','AGENCY_DEFINED')),CONSTRAINT ck_spms_dimension_weight CHECK(weight_percent>0));
CREATE TABLE "${primehrSchema}".spms_indicator_dimension_level(id VARCHAR(36) PRIMARY KEY,agency_id VARCHAR(64) NOT NULL,dimension_id VARCHAR(36) NOT NULL,rating_band_id VARCHAR(36) NOT NULL,comparison_operator VARCHAR(30) NOT NULL,threshold_from NUMERIC(19,6),threshold_to NUMERIC(19,6),manual_criteria VARCHAR(2000),record_version BIGINT NOT NULL DEFAULT 0,created_by VARCHAR(100) NOT NULL,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_by VARCHAR(100) NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL,CONSTRAINT fk_spms_level_dimension FOREIGN KEY(dimension_id) REFERENCES "${primehrSchema}".spms_indicator_dimension(id),CONSTRAINT fk_spms_level_band FOREIGN KEY(rating_band_id) REFERENCES "${primehrSchema}".spms_rating_band(id),CONSTRAINT uk_spms_indicator_dimension_band UNIQUE(agency_id,dimension_id,rating_band_id),CONSTRAINT ck_spms_level_operator CHECK(comparison_operator IN ('LT','LTE','EQ','GTE','GT','BETWEEN','MANUAL_CRITERIA')));
CREATE INDEX ix_spms_success_indicator_status ON "${primehrSchema}".spms_success_indicator_version(agency_id,status,policy_version_id);CREATE INDEX ix_spms_indicator_dimension ON "${primehrSchema}".spms_indicator_dimension(agency_id,indicator_version_id,display_order);CREATE INDEX ix_spms_indicator_level ON "${primehrSchema}".spms_indicator_dimension_level(agency_id,dimension_id);
